using FluentValidation;

namespace Surl.Api.Auth;

/// <summary>
/// NOTE: this reusable validator generated by AI is missing property name in its error message. 
/// refer to https://docs.fluentvalidation.net/en/latest/custom-validators.html# for reusing validation logic.
/// </summary>
public class StrongPasswordValidator : AbstractValidator<string>
  {
      public StrongPasswordValidator()
      {
          RuleFor(password => password)
              .Cascade(CascadeMode.Stop)
              .NotEmpty()
              .MinimumLength(12)
              .MaximumLength(50)
              .Matches("[A-Z]").WithMessage("Password must contain an uppercase letter.")
              .Matches("[a-z]").WithMessage("Password must contain a lowercase letter.")
              .Matches("[0-9]").WithMessage("Password must contain a number.")
              .Matches("[^a-zA-Z0-9]").WithMessage("Password must contain a special character.")
              .Matches("^\\S+$").WithMessage("Password must not contain whitespace.");
      }
  }
